```js
class AI {
 constructor(f){this.f=f;this.think=0;this.intent='wait';this.acted=false;this.blockHold=0;}
 update(dt, opp){
   const f=this.f;
   f.control.left=f.control.right=f.control.block=false;
   if (game.mode!=='fight' || f.state==='hit'||f.state==='ko'||f.state==='attack'||f.state==='win') return;
   this.blockHold=Math.max(0,this.blockHold-dt);
   this.think-=dt;
   const dist=Math.abs(opp.x-f.x);
   const dir=opp.x>f.x?1:-1;
   const incoming=projectiles.find(p=>p.owner===opp && Math.sign(f.x-p.x)===Math.sign(p.vx) && Math.abs(p.x-f.x)<430);
   if (this.think<=0) {
      this.think=0.09+Math.random()*0.16;
      this.choose(opp,dist,dir,incoming);
   }
   // react to incoming even between decisions
   if (incoming && this.intent!=='block' && this.intent!=='jump' && Math.random()<dt*8) {
      if (Math.random()<0.65) {this.intent='block';this.blockHold=.5;} else {this.intent='jump';this.acted=false;}
   }
   this.act(dt,opp,dist,dir);
 }
 choose(...) {
   this.acted=false;
   const r=Math.random();
   const p=opp;
   if (incoming) { if (r<.7) {this.intent='block';this.blockHold=.55;} else {this.intent='jump';} return; }
   if (p.state==='attack' && dist<210) { if(r<.55){this.intent='block';this.blockHold=.35;} else if(r<.7 && this.f.meter>=25){this.intent='uppercut';} else this.intent='retreat'; return;}
   if (!p.grounded && dist<200 && this.f.meter>=25 && r<.5) {this.intent='uppercut'; return;}
   if (dist>330) { if (r<.2 && this.f.meter>=25) this.intent='fireball'; else this.intent='approach'; }
   else if (dist>190) { if (r<.18 && this.f.meter>=25) this.intent='fireball'; else if(r<.3) this.intent='kick'; else this.intent='approach'; }
   else { if (r<.28) this.intent='punch'; else if (r<.55) this.intent='kick'; else if (r<.68 && this.f.meter>=25) this.intent=pick(['spin','uppercut','fireball']); else if (r<.8) this.intent='block'; else if (r<.9) this.intent='retreat'; else this.intent='approach'; }
 }
 act(dt,opp,dist,dir){
   const f=this.f;
   if (this.blockHold>0 || this.intent==='block') { f.control.block=true; if(this.blockHold>0)this.blockHold-=dt; return; }
   if (this.intent==='approach') { if(dist>88){ if(dir>0)f.control.right=true; else f.control.left=true; } else {this.intent='wait';} return; }
   if (this.intent==='retreat') { if(f.x>STAGE_L+40){ if(dir>0)f.control.left=true; else f.control.right=true;} return; }
   if (this.intent==='jump') { if(!this.acted){ f.tryJump(); this.acted=true; } this.intent='wait'; return;}
   if (!this.acted) {
     if (this.intent==='punch') f.tryAttack('punch');
     else if (this.intent==='kick') f.tryAttack('kick');
     else if (this.intent==='uppercut') f.trySpecial('uppercut');
     else if (this.intent==='fireball') f.trySpecial('fireball');
     else if (this.intent==='spin') f.trySpecial('spin');
     this.acted=true;
   }
   this.intent='wait';
 }
}
```
