  if (hudCache.p1g !== p1g) { hudCache.p1g = p1g; dom.p1ghost.style.width = p1g + '%'; }
  if (hudCache.p2g !== p2g) { hudCache.p2g = p2g; dom.p2ghost.style.width = p2g + '%'; }
