      dom.combo.classList.toggle('right', side === 'right');
      dom.combo.classList.add('show');
      comboShownSide = side; comboShownNum = num;
    }
  } else {
    dom.combo.classList.remove('show');
    comboShownSide = null; comboShownNum = 0;
  }
}

